package EmployeeManagementSystem.controller;
import EmployeeManagementSystem.entity.EmployeeAccessCardRequest; import EmployeeManagementSystem.security.jwt.JwtUtil; import EmployeeManagementSystem.repository.EmployeeRepository; import EmployeeManagementSystem.service.EmployeeAccessCardRequestService; import EmployeeManagementSystem.service.RequestScopeService;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@RestController @RequestMapping("/api/access-card-requests") public class EmployeeAccessCardRequestController{
 private final EmployeeAccessCardRequestService service; private final JwtUtil jwt; private final EmployeeRepository employees; private final RequestScopeService scope;
 public EmployeeAccessCardRequestController(EmployeeAccessCardRequestService s,JwtUtil j,EmployeeRepository e,RequestScopeService requestScope){service=s;jwt=j;employees=e;scope=requestScope;}
 private String tok(String a){if(a==null||!a.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Authentication required.");return a.substring(7);} private String user(String a){return jwt.extractUsername(tok(a));} private String role(String a){String r=jwt.extractRole(tok(a));return r==null?"":r.replace("ROLE_","").toUpperCase();} private boolean mgmt(String r){return Set.of("ADMIN","HR","MANAGER").contains(r);}
 private RuntimeException bad(Exception e){if(e instanceof SecurityException)return new ResponseStatusException(HttpStatus.FORBIDDEN,e.getMessage());return new ResponseStatusException(HttpStatus.BAD_REQUEST,e.getMessage());}
 @GetMapping("/my") public List<EmployeeAccessCardRequest> my(@RequestHeader("Authorization")String a){return service.my(user(a));}
 @GetMapping public List<EmployeeAccessCardRequest> all(@RequestHeader("Authorization")String a){String currentRole=role(a);if(!mgmt(currentRole))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");return scope.visibleTo(currentRole,user(a),service.all());}
 @PostMapping public EmployeeAccessCardRequest create(@RequestHeader("Authorization")String a,@RequestBody EmployeeAccessCardRequest x){String u=user(a);String n=employees.findByRegisterEmployee_UserId(u).map(e->e.getFullName()).orElse(u);try{return service.create(x,u,n);}catch(Exception e){throw bad(e);}}
 @PatchMapping("/{id}/review") public EmployeeAccessCardRequest review(@PathVariable Long id,@RequestHeader("Authorization")String a,@RequestBody Map<String,Object>b){String currentRole=role(a);if(!mgmt(currentRole))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Management access required.");scope.assertCanReviewById(currentRole,user(a),service.all(),id);try{return service.review(id,user(a),String.valueOf(b.get("status")),String.valueOf(b.getOrDefault("comment","")));}catch(Exception e){throw bad(e);}}
}
